 .../dce112/command_table_helper2_dce112.c     | 104 +-------------
 .../bios/dce112/command_table_helper_dce112.c | 104 +-------------
 .../bios/dce60/command_table_helper_dce60.c   | 106 +-------------
 .../bios/dce80/command_table_helper_dce80.c   | 106 +-------------
