 	if (ret < 0)
-		goto out;
+		return ret;

 	if (en)
 		ret &= ~VCNL4040_ALS_CONF_ALS_SHUTDOWN;
 	else
 		ret |= VCNL4040_ALS_CONF_ALS_SHUTDOWN;

-	ret = i2c_smbus_write_word_data(data->client, VCNL4200_AL_CONF, ret);
